const today = () => new Date().toISOString().slice(0, 10);
const activeCompanyId = () => readActiveCompanyId();
const stripMarkup = value => String(value || '').replace(/<[^>]*>/g, '').trim();

function WorkspaceShell({ title, description, onBack, children, badge = 'Company-scoped configuration' }) {
  return <div className="page-content operational-workspace canonical-workspace"><button className="inline-back" onClick={onBack}><ArrowLeft /> Back</button><div className="page-heading"><div><p className="breadcrumb">Atlas / {title}</p><h1>{title}</h1><p className="page-description">{description}</p></div><span className="controlled-badge"><ShieldCheck /> {badge}</span></div>{children}</div>;
}

function Tabs({ tabs, active, onChange }) {
  return <nav className="workspace-tabs" aria-label="Workspace sections">{tabs.map(tab => <button key={tab} className={active === tab ? 'active' : ''} onClick={() => onChange(tab)}>{tab}</button>)}</nav>;
}

function SaveBar({ onCancel, onSave, label = 'Save changes', submit = true }) {
  return <div className="canonical-save-bar"><button type="button" className="button secondary" onClick={onCancel}>Cancel</button><button type={submit ? 'submit' : 'button'} className="button primary" onClick={onSave}><Check /> {label}</button></div>;
}

function SecurityPolicy({ companyId, notify }) {
  const [policy, setPolicy] = useState(() => readSecurityPolicy(companyId));
  const [dirty, setDirty] = useState(false);
  const set = (key, value) => { setPolicy(previous => ({ ...previous, [key]: value })); setDirty(true); };
  const toggleMfa = method => set('mfaMethods', policy.mfaMethods.includes(method) ? policy.mfaMethods.filter(item => item !== method) : [...policy.mfaMethods, method]);
  const save = () => {
    if (policy.mfaRequired && !policy.mfaMethods.length) return notify({ type: 'error', message: 'At least one supported MFA method is required.' });
    if (Number(policy.inactivityTimeoutSeconds) < 30) return notify({ type: 'error', message: 'Inactivity timeout cannot be below the 30-second BRD minimum.' });
    setPolicy(saveSecurityPolicy(policy)); setDirty(false); notify({ type: 'success', message: 'Security policy saved and audited.' });
  };
  return <section className="canonical-card"><div className="canonical-card-header"><div><h2>Session and identity policy</h2><p>Authentication and session controls are enforced by the security service. Role switching in this prototype is presentation-only.</p></div><span className="status-pill active">v{policy.version}</span></div><div className="canonical-form-grid"><label>Authentication mode<input value={policy.authMode} readOnly /></label><label>External identity provider<input value={policy.ssoProvider} readOnly /></label><label>Password expiration<input value={policy.passwordMode} readOnly /><small>For O365-tied identities this is managed by the identity provider.</small></label><label>Inactivity timeout (seconds)<input type="number" min="30" value={policy.inactivityTimeoutSeconds} onChange={event => set('inactivityTimeoutSeconds', event.target.value)} /><small>BRD specifies 30 seconds; the legacy 30-minute visual seed is not applied silently.</small></label><label>Warning before timeout (seconds)<input type="number" min="0" value={policy.warningSeconds} onChange={event => set('warningSeconds', event.target.value)} /></label><label>Maximum session age (hours)<input type="number" min="1" value={policy.sessionMaxAgeHours} onChange={event => set('sessionMaxAgeHours', event.target.value)} /></label><label>Failed attempts before lockout<input type="number" min="1" value={policy.lockoutAttempts} onChange={event => set('lockoutAttempts', event.target.value)} /></label><label>Lockout duration (minutes)<input type="number" min="1" value={policy.lockoutMinutes} onChange={event => set('lockoutMinutes', event.target.value)} /></label></div><div className="canonical-subsection"><h3><LockKey /> Multi-factor authentication</h3><label className="toggle-row"><input type="checkbox" checked={policy.mfaRequired} onChange={event => set('mfaRequired', event.target.checked)} /><span><strong>Require MFA for sensitive actions</strong><small>Enabled by default for Security, User Rights, Company Rules and exports.</small></span></label><div className="check-grid">{['SMS', 'Microsoft Authenticator'].map(method => <label key={method}><input type="checkbox" checked={policy.mfaMethods.includes(method)} onChange={() => toggleMfa(method)} /> {method}</label>)}{Object.entries(policy.capabilityGatedMethods).map(([method, status]) => <label className="disabled-check" key={method}><input type="checkbox" disabled /> {method} <small>{status}</small></label>)}</div></div><div className="canonical-callout"><Warning /><span><strong>Identity boundary:</strong> reset password is not offered for O365-tied identities, and changing the demo role cannot grant company access.</span></div>{dirty && <SaveBar onCancel={() => { setPolicy(readSecurityPolicy(companyId)); setDirty(false); }} onSave={save} />}</section>;
}

function ReportProtection({ companyId, notify }) {
  const [config, setConfig] = useState(() => readReportProtection(companyId));
  const [dirty, setDirty] = useState(false);
  const save = () => { setConfig(saveReportProtection(config)); setDirty(false); notify({ type: 'success', message: 'Report protection settings saved. No plaintext passphrase was stored.' }); };
  const rotate = () => { const next = { ...config, lastRotatedAt: new Date().toISOString(), rotationRequiredDays: 90 }; setConfig(next); setDirty(true); notify({ type: 'success', message: 'A secret rotation request was staged for the managed vault.' }); };
  return <section className="canonical-card"><div className="canonical-card-header"><div><h2>Report protection</h2><p>Separate from login security. Reports use managed secret references and encrypted ZIP/export delivery.</p></div><span className="status-pill active">{config.enabled ? 'Enabled' : 'Disabled'}</span></div><div className="canonical-form-grid"><label className="toggle-row"><input type="checkbox" checked={config.enabled} onChange={event => { setConfig({ ...config, enabled: event.target.checked }); setDirty(true); }} /><span><strong>Protect generated reports</strong><small>Report viewers never receive stored plaintext passphrases.</small></span></label><label>Secret provider<input value={config.provider} readOnly /></label><label>Default secret reference<input value={config.defaultSecretRef} readOnly /></label><label>Rotation interval (days)<input type="number" min="1" value={config.rotationRequiredDays} onChange={event => { setConfig({ ...config, rotationRequiredDays: event.target.value }); setDirty(true); }} /></label></div><div className="canonical-subsection"><h3>Protected report groups</h3><div className="canonical-list">{config.groups.map(group => <div className="canonical-list-row" key={group.id}><div><strong>{group.name}</strong><small>{group.delivery} · {group.secretRef}</small></div><span className="status-pill active">{group.status}</span></div>)}</div></div><div className="canonical-actions"><button className="button secondary" onClick={rotate}><LockKey /> Request secret rotation</button>{dirty && <button className="button primary" onClick={save}><Check /> Save protection</button>}</div></section>;
}

function Entitlements({ companyId, notify }) {
  const [features, setFeatures] = useState(() => readFeatureEntitlements(companyId));
  const company = getCompany(companyId);
  const enrolled = new Set((company?.serviceEnrollments || []).filter(item => item.enabled).map(item => item.serviceCode));
  const save = () => { setFeatures(saveFeatureEntitlements(features)); notify({ type: 'success', message: 'Feature entitlement changes saved and audited.' }); };
  return <section className="canonical-card"><div className="canonical-card-header"><div><h2>Modules and feature entitlements</h2><p>Feature switches consume company onboarding/service enrollment. An unentitled service cannot be enabled here.</p></div></div><div className="canonical-list">{features.map(feature => <div className="canonical-list-row" key={feature.featureCode}><div><strong>{feature.label}</strong><small>{feature.detail} · Service: {feature.serviceCode}</small></div><label className="toggle-row compact"><input type="checkbox" checked={feature.enabled} disabled={!enrolled.has(feature.serviceCode)} onChange={event => setFeatures(previous => previous.map(item => item.featureCode === feature.featureCode ? { ...item, enabled: event.target.checked } : item))} /><span>{enrolled.has(feature.serviceCode) ? feature.status : 'Not entitled'}</span></label></div>)}</div><div className="canonical-actions"><button className="button primary" onClick={save}><Check /> Save entitlements</button></div></section>;
}

function FieldMetadata({ companyId, notify }) {
  const [fields, setFields] = useState(() => readFieldMetadata(companyId));
  const save = () => { try { setFields(saveFieldMetadata(fields)); notify({ type: 'success', message: 'Field visibility saved. Requiredness remains read-only.' }); } catch (error) { notify({ type: 'error', message: error.message }); } };
  return <section className="canonical-card"><div className="canonical-card-header"><div><h2>Field metadata and visibility</h2><p>Required fields cannot be made optional. Only optional visibility is configurable, with field keys and permission checks retained.</p></div></div><div className="table-card canonical-inner-table"><table><thead><tr><th>Field</th><th>Domain</th><th>Bulk update</th><th>Sensitivity</th><th>Requiredness</th><th>Visibility</th></tr></thead><tbody>{fields.map(field => <tr key={field.fieldKey}><td><code>{field.fieldKey}</code><small>{field.displayLabel}</small></td><td>{field.domain}</td><td>{field.bulkUpdateAllowed ? 'Allowed' : 'No'}</td><td>{field.sensitive ? 'Sensitive' : 'Standard'}</td><td>{field.requiredness}</td><td><select value={field.visibility} disabled={field.requiredness.startsWith('Required')} onChange={event => setFields(previous => previous.map(item => item.fieldKey === field.fieldKey ? { ...item, visibility: event.target.value } : item))}><option>Visible</option><option>Hidden</option></select></td></tr>)}</tbody></table></div><div className="canonical-actions"><button className="button primary" onClick={save}><Check /> Save field settings</button></div></section>;
}

function Preferences({ companyId, notify }) {
  const [preferences, setPreferences] = useState(() => readPreferences(companyId));
  const set = (key, value) => setPreferences(previous => ({ ...previous, [key]: value }));
  const save = () => { setPreferences(savePreferences(preferences)); notify({ type: 'success', message: 'Presentation preferences saved.' }); };
  return <section className="canonical-card"><div className="canonical-card-header"><div><h2>Presentation preferences</h2><p>These settings change the experience only; they cannot bypass security, payroll validation, or authorization.</p></div></div><div className="canonical-form-grid"><label>Theme<select value={preferences.theme} onChange={event => set('theme', event.target.value)}><option>Light</option><option>Dark</option><option>System</option></select></label><label>Density<select value={preferences.density} onChange={event => set('density', event.target.value)}><option>Comfortable</option><option>Compact</option></select></label><label>Date format<select value={preferences.dateFormat} onChange={event => set('dateFormat', event.target.value)}><option>MM/DD/YYYY</option><option>DD/MM/YYYY</option><option>YYYY-MM-DD</option></select></label><label>Time zone<select value={preferences.timeZone} onChange={event => set('timeZone', event.target.value)}><option>Asia/Manila</option><option>UTC</option><option>Asia/Singapore</option></select></label><label>Default landing page<select value={preferences.defaultLanding} onChange={event => set('defaultLanding', event.target.value)}><option>Company Information</option><option>Services Information</option><option>Company Rules</option></select></label><label>Email digest<select value={preferences.emailDigest} onChange={event => set('emailDigest', event.target.value)}><option>Immediate</option><option>Daily</option><option>Weekly</option><option>None</option></select></label></div><div className="canonical-actions"><button className="button primary" onClick={save}><Check /> Save preferences</button></div></section>;
}

export function SecurityWorkspace({ onBack, notify, companyId = activeCompanyId() }) {
  const [tab, setTab] = useState('Security Policy');
  const tabs = ['Security Policy', 'Report Protection', 'Feature Entitlements', 'Field Visibility', 'Preferences'];
  return <WorkspaceShell title="Security Configuration" description="Manage identity/session controls, report protection, entitled modules, field metadata and presentation preferences for the selected company." onBack={onBack} badge="Security service boundary"><Tabs tabs={tabs} active={tab} onChange={setTab} />{tab === 'Security Policy' && <SecurityPolicy companyId={companyId} notify={notify} />}{tab === 'Report Protection' && <ReportProtection companyId={companyId} notify={notify} />}{tab === 'Feature Entitlements' && <Entitlements companyId={companyId} notify={notify} />}{tab === 'Field Visibility' && <FieldMetadata companyId={companyId} notify={notify} />}{tab === 'Preferences' && <Preferences companyId={companyId} notify={notify} />}</WorkspaceShell>;
}

function readScopedRows(key, fallback, companyId) {
  try {
    const saved = JSON.parse(localStorage.getItem(key));
    const rows = Array.isArray(saved) ? saved.filter(item => item.companyId === companyId) : [];
    return rows.length ? rows : fallback.map(item => ({ ...item, companyId }));
  } catch { return fallback.map(item => ({ ...item, companyId })); }
}
function writeScopedRows(key, rows, companyId) {
  let existing = [];
  try { existing = JSON.parse(localStorage.getItem(key)) || []; } catch { existing = []; }
  localStorage.setItem(key, JSON.stringify([...rows, ...existing.filter(item => item.companyId !== companyId)]));
}

export function AccessRightsWorkspace({ onBack, notify, companyId = activeCompanyId() }) {
  const [tab, setTab] = useState('User Rights');
  const [roles] = useState(() => readScopedRows('atlas-security-roles-v1', readRoles(companyId), companyId));
  const [grants, setGrants] = useState(() => readScopedRows('atlas-security-grants-v1', readGrants(companyId), companyId));
  const [draft, setDraft] = useState(null);
  const tabs = ['User Rights', 'Approval Hierarchy'];
  const saveGrant = event => { event.preventDefault(); if (!draft.user || !draft.role || !draft.module) return notify({ type: 'error', message: 'User, role and module are required.' }); const next = draft.id ? grants.map(item => item.id === draft.id ? draft : item) : [{ ...draft, id: `grant-${Date.now()}`, companyId }, ...grants]; setGrants(next); writeScopedRows('atlas-security-grants-v1', next, companyId); appendAuditEvent({ companyId, actor: 'Client Admin', action: 'UserGrantUpdated', entityType: 'UserGrant', entityId: draft.id || 'new', summary: `${draft.user} ${draft.id ? 'updated' : 'granted'} ${draft.role} access.` }); setDraft(null); notify({ type: 'success', message: 'Company-scoped access grant saved.' }); };
  return <WorkspaceShell title="Access & Approvals" description="Manage company-scoped roles, permissions, grants and a multi-level approval hierarchy. Authorization remains a service boundary, not a visual role switch." onBack={onBack} badge="Authorization service boundary"><Tabs tabs={tabs} active={tab} onChange={setTab} />{tab === 'User Rights' ? <><div className="canonical-toolbar"><div><strong>{grants.filter(item => item.status === 'Active').length}</strong><span> active {plural(grants.filter(item => item.status === 'Active').length, 'grant')} in this company</span></div><button className="button primary" onClick={() => setDraft({ user: '', role: roles[0]?.name || '', module: '', feature: '', permission: '', approvalLevel: 'None', status: 'Active', companyId })}><Plus /> Add grant</button></div><div className="canonical-role-grid">{roles.map(role => <div className="canonical-role-card" key={role.id}><strong>{role.name}</strong><small>{role.description}</small><span>{role.permissionCount} permissions · {role.status}</span></div>)}</div><div className="table-card canonical-inner-table"><table><thead><tr><th>User</th><th>Role</th><th>Module / feature</th><th>Permission</th><th>Approval</th><th>Status</th><th>Action</th></tr></thead><tbody>{grants.map(grant => <tr key={grant.id}><td>{grant.user}</td><td>{grant.role}</td><td>{grant.module}<small>{grant.feature}</small></td><td>{grant.permission}</td><td>{grant.approvalLevel}</td><td><span className={`status-pill ${grant.status.toLowerCase()}`}>{grant.status}</span></td><td><button className="icon-button" onClick={() => setDraft(grant)} aria-label="Edit access grant"><PencilSimple /></button></td></tr>)}</tbody></table></div>{draft && <div className="modal-backdrop"><section className="modal canonical-modal"><header><h2>{draft.id ? 'Edit access grant' : 'Add access grant'}</h2><button className="icon-button" onClick={() => setDraft(null)}><X /></button></header><form onSubmit={saveGrant}><div className="canonical-form-grid"><label>User / employee<input required value={draft.user} onChange={event => setDraft({ ...draft, user: event.target.value })} /></label><label>Role<select value={draft.role} onChange={event => setDraft({ ...draft, role: event.target.value })}>{roles.map(role => <option key={role.id}>{role.name}</option>)}</select></label><label>Module / feature<input required value={draft.module} onChange={event => setDraft({ ...draft, module: event.target.value })} placeholder="e.g. Company Rules" /></label><label>Feature<input value={draft.feature} onChange={event => setDraft({ ...draft, feature: event.target.value })} /></label><label>Permission<input value={draft.permission} onChange={event => setDraft({ ...draft, permission: event.target.value })} placeholder="View, Edit, Approve" /></label><label>Approval level<select value={draft.approvalLevel} onChange={event => setDraft({ ...draft, approvalLevel: event.target.value })}><option>None</option><option>Level 1</option><option>Level 2</option><option>Level 3</option><option>Level 4</option><option>Level 5</option><option>Level 6</option><option>Final</option></select></label></div><SaveBar onCancel={() => setDraft(null)} onSave={() => {}} label="Save grant" /></form></section></div>}</> : <ApprovalHierarchy companyId={companyId} notify={notify} />}</WorkspaceShell>;
}

function ApprovalHierarchy({ companyId, notify }) {
  const [levels, setLevels] = useState(() => readScopedRows('atlas-approval-hierarchy-v1', [{ level: 1, mode: 'Sequential', approvers: 'Preparer' }, { level: 2, mode: 'Parallel', approvers: 'Checker, Reviewer' }, { level: 3, mode: 'Sequential', approvers: 'Client Admin' }], companyId));
  const save = () => { writeScopedRows('atlas-approval-hierarchy-v1', levels, companyId); appendAuditEvent({ companyId, actor: 'Client Admin', action: 'ApprovalHierarchyUpdated', entityType: 'ApprovalHierarchy', entityId: companyId, summary: `${levels.length}-level approval hierarchy saved.` }); notify({ type: 'success', message: 'Approval hierarchy saved and audited.' }); };
  return <section className="canonical-card"><div className="canonical-card-header"><div><h2>Multi-level approval hierarchy</h2><p>Configure up to six levels, with parallel approvers where the policy requires it.</p></div><span className="status-pill active">Company scoped</span></div><div className="table-card canonical-inner-table"><table><thead><tr><th>Level</th><th>Mode</th><th>Approvers</th><th>Action</th></tr></thead><tbody>{levels.map((row, index) => <tr key={row.level}><td><strong>Level {row.level}</strong></td><td><select value={row.mode} onChange={event => setLevels(previous => previous.map((item, i) => i === index ? { ...item, mode: event.target.value } : item))}><option>Sequential</option><option>Parallel</option></select></td><td><input value={row.approvers} onChange={event => setLevels(previous => previous.map((item, i) => i === index ? { ...item, approvers: event.target.value } : item))} /></td><td><button className="icon-button" disabled={levels.length <= 1} onClick={() => setLevels(previous => previous.filter((_, i) => i !== index))}><X /></button></td></tr>)}</tbody></table></div><div className="canonical-actions"><button className="button secondary" disabled={levels.length >= 6} onClick={() => setLevels(previous => [...previous, { level: previous.length + 1, mode: 'Sequential', approvers: '' }])}><Plus /> Add level</button><button className="button primary" onClick={save}><Check /> Save hierarchy</button></div></section>;
}

