/**
 * The company's calendars, for a module that needs them without opening the
 * screen. The calendar is company-scoped and seeds itself on first read, so
 * payroll must come through here rather than reading the storage key directly.
 */
export function readCalendars(companyId = activeCompanyId(), type) {
  const rows = readScopedRows('atlas-operational-calendar-v1', calendarSeed, companyId);
  return type ? rows.filter(row => row.calendarType === type && row.status === 'Active') : rows;
}

function LegacyCalendarWorkspace({ onBack, notify, companyId = activeCompanyId() }) {
  const [rows, setRows] = useState(() => readScopedRows('atlas-operational-calendar-v1', calendarSeed, companyId));
  const [editing, setEditing] = useState(null);
  const [query, setQuery] = useState('');
  const visible = useMemo(() => rows.filter(row => Object.values(row).join(' ').toLowerCase().includes(query.toLowerCase())), [rows, query]);
  const save = event => { event.preventDefault(); const item = editing; if (!item.calendarCode || !item.calendarType || !item.frequency || !item.effectiveFrom) return notify({ type: 'error', message: 'Calendar code, type, frequency and effective-from date are required.' }); const overlap = rows.some(row => row.id !== item.id && row.calendarType === item.calendarType && row.status === 'Active' && (!item.effectiveTo || !row.effectiveTo || item.effectiveFrom <= row.effectiveTo) && (!row.effectiveTo || row.effectiveTo >= item.effectiveFrom)); if (overlap) return notify({ type: 'error', message: 'An active calendar of this type overlaps the effective period.' }); const next = item.id ? rows.map(row => row.id === item.id ? { ...item, version: Number(row.version || 0) + 1 } : row) : [{ ...item, id: `cal-${Date.now()}`, companyId, version: 1 }, ...rows]; setRows(next); writeScopedRows('atlas-operational-calendar-v1', next, companyId); appendAuditEvent({ companyId, actor: 'Client Admin', action: 'CalendarChanged', entityType: 'Calendar', entityId: item.id || 'new', summary: `${item.calendarCode} ${item.status === 'Active' ? 'published' : 'saved as draft'}.` }); setEditing(null); notify({ type: 'success', message: 'Calendar saved; dependent payroll/timekeeping services will read the canonical version.' }); };
  return <WorkspaceShell title="Calendar Settings" description="Maintain the company-scoped calendar consumed by payroll, timekeeping, statutory and billing domains. Billing cutoffs remain owned by Billing." onBack={onBack} badge="Canonical Calendar Service"><div className="canonical-toolbar"><div className="search-box"><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Search calendar..." /><MagnifyingGlass /></div><div className="toolbar-spacer" /><button className="button primary" onClick={() => setEditing({ calendarCode: '', calendarType: 'Payout', frequency: 'Semi-monthly', effectiveFrom: today(), effectiveTo: '', payoutDate: '', processDate: '', holidayGroup: 'Philippine National', status: 'Draft' })}><Plus /> Add calendar</button></div><div className="canonical-callout"><Clock /><span><strong>Publishing emits CalendarChanged.</strong> Used calendar versions are not deleted; set them inactive and preserve their effectivity for historical payroll reproducibility.</span></div><div className="table-card canonical-inner-table"><table><thead><tr><th>Code</th><th>Type</th><th>Frequency</th><th>Effective</th><th>Process / payout</th><th>Holiday group</th><th>Status</th><th>Action</th></tr></thead><tbody>{visible.map(row => <tr key={row.id}><td><code>{row.calendarCode}</code><small>v{row.version}</small></td><td>{row.calendarType}</td><td>{row.frequency}</td><td>{row.effectiveFrom}{row.effectiveTo ? ` – ${row.effectiveTo}` : ' onward'}</td><td>{row.processDate || row.payoutDate || '—'}</td><td>{row.holidayGroup || '—'}</td><td><span className={`status-pill ${row.status.toLowerCase()}`}>{row.status}</span></td><td><button className="icon-button" onClick={() => setEditing(row)} aria-label="Edit calendar"><PencilSimple /></button></td></tr>)}</tbody></table></div>{editing && <div className="modal-backdrop"><section className="modal canonical-modal"><header><h2>{editing.id ? 'Edit calendar' : 'Add calendar'}</h2><button className="icon-button" onClick={() => setEditing(null)}><X /></button></header><form onSubmit={save}><div className="canonical-form-grid"><label>Calendar code<input required value={editing.calendarCode} onChange={event => setEditing({ ...editing, calendarCode: event.target.value })} /></label><label>Calendar type<select value={editing.calendarType} onChange={event => setEditing({ ...editing, calendarType: event.target.value })}><option>Payout</option><option>Payroll Process</option><option>Timekeeping</option><option>Statutory</option><option>Holiday</option><option>Billing Cutoff</option></select></label><label>Frequency<select value={editing.frequency} onChange={event => setEditing({ ...editing, frequency: event.target.value })}><option>Daily</option><option>Weekly</option><option>Semi-monthly</option><option>Monthly</option><option>Annual</option></select></label><label>Effective from<input type="date" required value={editing.effectiveFrom} onChange={event => setEditing({ ...editing, effectiveFrom: event.target.value })} /></label><label>Effective to<input type="date" value={editing.effectiveTo || ''} onChange={event => setEditing({ ...editing, effectiveTo: event.target.value })} /></label><label>Process date<input type="date" value={editing.processDate || ''} onChange={event => setEditing({ ...editing, processDate: event.target.value })} /></label><label>Payout date<input type="date" value={editing.payoutDate || ''} onChange={event => setEditing({ ...editing, payoutDate: event.target.value })} /></label><label>Holiday group<select value={editing.holidayGroup} onChange={event => setEditing({ ...editing, holidayGroup: event.target.value })}><option>Philippine National</option><option>Company</option><option>Location-specific</option></select></label><label>Status<select value={editing.status} onChange={event => setEditing({ ...editing, status: event.target.value })}><option>Draft</option><option>Active</option><option>Inactive</option></select></label></div><SaveBar onCancel={() => setEditing(null)} onSave={() => {}} label="Save calendar" /></form></section></div>}</WorkspaceShell>;
}

export function CalendarWorkspace({ onBack, notify, companyId = activeCompanyId() }) {
  const [rows, setRows] = useState(() => {
    const stored = readScopedRows('atlas-operational-calendar-v1', calendarSeed, companyId);
    const existingCodes = new Set(stored.map(row => row.calendarCode));
    return [...stored, ...calendarSeed.filter(row => !existingCodes.has(row.calendarCode)).map(row => ({ ...row, companyId }))];
  });
  const [editing, setEditing] = useState(null);
  const [query, setQuery] = useState('');
  const uploadRef = useRef(null);
  const visible = useMemo(() => rows.filter(row => Object.values(row).join(' ').toLowerCase().includes(query.toLowerCase())), [rows, query]);
  const fields = ['calendarCode', 'calendarType', 'frequency', 'effectiveFrom', 'effectiveTo', 'processDate', 'payoutDate', 'cutoffStart', 'cutoffEnd', 'releaseDate', 'holidayName', 'holidayClass', 'holidayGroup', 'leadTimeDays', 'approvalLevels', 'status'];
  const labels = ['Calendar Code', 'Calendar Type', 'Frequency', 'Effective From', 'Effective To', 'Process / Deadline Date', 'Payout Date', 'Cutoff Start', 'Cutoff End', 'Billing Release Date', 'Holiday Name', 'Holiday Classification', 'Holiday Group', 'Reminder Lead Days', 'Approval Levels', 'Status'];

  const persist = next => { setRows(next); writeScopedRows('atlas-operational-calendar-v1', next, companyId); };
  const save = event => {
    event.preventDefault();
    const item = { ...editing };
    if (!item.calendarCode || !item.calendarType || !item.frequency || !item.effectiveFrom) return notify({ type: 'error', message: 'Calendar code, type, frequency and effective-from date are required.' });
    if (rows.some(row => row.id !== item.id && row.calendarCode === item.calendarCode)) return notify({ type: 'error', message: `${item.calendarCode} already exists. Edit the existing calendar or use a new code.` });
    if (Number(item.approvalLevels || 1) < 1 || Number(item.approvalLevels || 1) > 6) return notify({ type: 'error', message: 'Approval levels must be between 1 and 6.' });
    if (item.calendarType === 'Payout' && (!item.processDate || !item.payoutDate)) return notify({ type: 'error', message: 'A payout calendar requires both process and payout dates.' });
    if (item.calendarType === 'Billing Cutoff' && (!item.cutoffStart || !item.cutoffEnd || !item.releaseDate)) return notify({ type: 'error', message: 'A billing cutoff requires start, end and release dates.' });
    if (item.calendarType === 'Holiday' && (!item.holidayName || !item.processDate || !item.holidayClass)) return notify({ type: 'error', message: 'A holiday requires a name, date and classification.' });
    const prepared = item.id ? { ...item, version: Number(item.version || 0) + 1 } : { ...item, id: `cal-${Date.now()}`, companyId, version: 1 };
    const next = item.id ? rows.map(row => row.id === item.id ? prepared : row) : [prepared, ...rows];
    persist(next);
    appendAuditEvent({ companyId, actor: 'Client Admin', action: 'CalendarChanged', entityType: 'Calendar', entityId: prepared.calendarCode, summary: `${prepared.calendarType} ${prepared.calendarCode} saved as ${prepared.status}.` });
    publishNotificationEvent({ eventKey: 'CalendarEventDue', companyId, correlationId: prepared.calendarCode, summary: `${prepared.calendarCode} calendar saved with ${prepared.leadTimeDays || 0}-day reminder lead time.`, actor: 'Client Admin' });
    setEditing(null);
    notify({ type: 'success', message: 'Calendar saved and published to dependent payroll, statutory, billing and notification services.' });
  };
  const startAdd = () => setEditing({ calendarCode: '', calendarType: 'Payout', frequency: 'Semi-monthly', effectiveFrom: today(), effectiveTo: '', processDate: '', payoutDate: '', cutoffStart: '', cutoffEnd: '', releaseDate: '', holidayName: '', holidayClass: 'Regular Holiday', holidayGroup: 'Philippine National', leadTimeDays: '3', approvalLevels: '3', status: 'Draft' });
  const exportRows = () => {
    const csv = [labels.map(label => `"${label}"`).join(','), ...visible.map(row => fields.map(field => `"${String(row[field] || '').replaceAll('"', '""')}"`).join(','))].join('\n');
    downloadFile('payroll-calendar.csv', csv, 'text/csv');
    notify({ type: 'success', message: `${visible.length} ${plural(visible.length, 'calendar record')} exported.` });
  };
  const downloadTemplate = () => downloadFile('payroll-calendar-upload-template.csv', `${labels.map(label => `"${label}"`).join(',')}\n${fields.map(() => '').join(',')}\n`, 'text/csv');
  const importRows = event => {
    const file = event.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
      const lines = String(reader.result).split(/\r?\n/).filter(Boolean);
      const headers = (lines.shift() || '').split(',').map(value => value.replaceAll('"', '').trim().toLowerCase());
      const required = ['Calendar Code', 'Calendar Type', 'Frequency', 'Effective From'];
      const missing = required.filter(label => !headers.includes(label.toLowerCase()));
      if (missing.length) return notify({ type: 'error', message: `Missing required columns: ${missing.join(', ')}.` });
      const imported = lines.map((line, index) => {
        const values = line.split(',').map(value => value.replace(/^"|"$/g, '').trim());
        const item = { id: `cal-import-${Date.now()}-${index}`, companyId, version: 1, status: 'Draft' };
        fields.forEach((field, fieldIndex) => { const position = headers.findIndex(header => header === field.toLowerCase() || header === labels[fieldIndex].toLowerCase()); if (position >= 0) item[field] = values[position]; });
        return item;
      }).filter(item => item.calendarCode && !rows.some(row => row.calendarCode === item.calendarCode));
      if (!imported.length) return notify({ type: 'error', message: 'No new calendar rows were found.' });
      persist([...imported, ...rows]);
      appendAuditEvent({ companyId, actor: 'Client Admin', action: 'CalendarImported', entityType: 'Calendar', entityId: file.name, summary: `${imported.length} calendar rows imported as Draft.` });
      notify({ type: 'success', message: `${imported.length} ${plural(imported.length, 'calendar record')} imported as Draft for review.` });
    };
    reader.readAsText(file);
    event.target.value = '';
  };
  const remove = row => {
    if (row.status !== 'Draft') return notify({ type: 'error', message: 'Published calendar versions are retained. Set the record inactive instead of deleting it.' });
    persist(rows.filter(item => item.id !== row.id));
    appendAuditEvent({ companyId, actor: 'Client Admin', action: 'CalendarDraftDeleted', entityType: 'Calendar', entityId: row.calendarCode, summary: `${row.calendarCode} draft deleted.` });
    notify({ type: 'success', message: `${row.calendarCode} draft deleted.` });
  };

  return <WorkspaceShell title="Calendar Settings" description="Maintain the company calendar consumed by payroll, timekeeping, statutory, billing and notification services." onBack={onBack} badge="Canonical Calendar Service">
    <div className="canonical-toolbar"><div className="search-box"><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Search calendar..." /><MagnifyingGlass /></div><div className="toolbar-spacer" /><button className="button primary" onClick={startAdd}><Plus /> Add calendar</button><button className="button secondary" onClick={downloadTemplate}><FileCsv /> Template</button><button className="button secondary" onClick={() => uploadRef.current?.click()}><UploadSimple /> Upload</button><input className="sr-only" ref={uploadRef} type="file" accept=".csv" onChange={importRows} /><button className="button secondary" onClick={exportRows}><DownloadSimple /> Export</button></div>
    <div className="canonical-callout"><Clock /><span><strong>One calendar, multiple consumers.</strong> Payouts, process deadlines, statutory due dates, holidays and billing cutoffs remain separate record types and publish reminder events using their configured lead time.</span></div>
    <div className="table-card canonical-inner-table"><table><thead><tr><th>Code</th><th>Type</th><th>Frequency</th><th>Effective</th><th>Key date</th><th>Approvals / reminder</th><th>Status</th><th>Action</th></tr></thead><tbody>{visible.map(row => <tr key={row.id}><td><code>{row.calendarCode}</code><small>v{row.version}</small></td><td>{row.calendarType}</td><td>{row.frequency}</td><td>{row.effectiveFrom}{row.effectiveTo ? ` – ${row.effectiveTo}` : ' onward'}</td><td>{row.payoutDate || row.processDate || row.releaseDate || row.cutoffEnd || '—'}<small>{row.holidayName || (row.cutoffStart && row.cutoffEnd ? `${row.cutoffStart} to ${row.cutoffEnd}` : '')}</small></td><td>{row.approvalLevels || 1} {plural(Number(row.approvalLevels || 1), 'level')}<small>{row.leadTimeDays || 0} reminder days</small></td><td><span className={`status-pill ${row.status.toLowerCase()}`}>{row.status}</span></td><td><div className="row-actions always"><button onClick={() => setEditing(row)} aria-label="Edit calendar"><PencilSimple /></button><button onClick={() => remove(row)} aria-label="Delete calendar"><Trash /></button></div></td></tr>)}</tbody></table></div>
    <div className="pagination"><span>Displaying <strong>{visible.length}</strong> of {rows.length} {plural(rows.length, 'calendar record')}</span><span>1 of 1</span></div>
    {editing && <div className="modal-backdrop"><section className="modal canonical-modal"><header><h2>{editing.id ? 'Edit calendar' : 'Add calendar'}</h2><button className="icon-button" onClick={() => setEditing(null)}><X /></button></header><form onSubmit={save}><div className="canonical-form-grid"><label>Calendar code<span className="required">*</span><input required value={editing.calendarCode} onChange={event => setEditing({ ...editing, calendarCode: event.target.value.toUpperCase() })} /></label><label>Calendar type<span className="required">*</span><select value={editing.calendarType} onChange={event => setEditing({ ...editing, calendarType: event.target.value })}><option>Payout</option><option>Payroll Process</option><option>Timekeeping</option><option>Statutory</option><option>Holiday</option><option>Billing Cutoff</option></select></label><label>Frequency<span className="required">*</span><select value={editing.frequency} onChange={event => setEditing({ ...editing, frequency: event.target.value })}><option>Daily</option><option>Weekly</option><option>Semi-monthly</option><option>Monthly</option><option>Annual</option></select></label><label>Effective from<span className="required">*</span><input type="date" required value={editing.effectiveFrom} onChange={event => setEditing({ ...editing, effectiveFrom: event.target.value })} /></label><label>Effective to<input type="date" value={editing.effectiveTo || ''} onChange={event => setEditing({ ...editing, effectiveTo: event.target.value })} /></label><label>Process / deadline date<input type="date" value={editing.processDate || ''} onChange={event => setEditing({ ...editing, processDate: event.target.value })} /></label><label>Payout date<input type="date" value={editing.payoutDate || ''} onChange={event => setEditing({ ...editing, payoutDate: event.target.value })} /></label><label>Cutoff start<input type="date" value={editing.cutoffStart || ''} onChange={event => setEditing({ ...editing, cutoffStart: event.target.value })} /></label><label>Cutoff end<input type="date" value={editing.cutoffEnd || ''} onChange={event => setEditing({ ...editing, cutoffEnd: event.target.value })} /></label><label>Billing release date<input type="date" value={editing.releaseDate || ''} onChange={event => setEditing({ ...editing, releaseDate: event.target.value })} /></label><label>Holiday name<input value={editing.holidayName || ''} onChange={event => setEditing({ ...editing, holidayName: event.target.value })} /></label><label>Holiday classification<select value={editing.holidayClass || 'Regular Holiday'} onChange={event => setEditing({ ...editing, holidayClass: event.target.value })}><option>Regular Holiday</option><option>Special Non-working Holiday</option><option>Regular Holiday on Rest Day</option><option>Special Holiday on Rest Day</option></select></label><label>Holiday group<select value={editing.holidayGroup || 'Philippine National'} onChange={event => setEditing({ ...editing, holidayGroup: event.target.value })}><option>Philippine National</option><option>Company</option><option>Location-specific</option><option>International</option></select></label><label>Reminder lead days<input type="number" min="0" value={editing.leadTimeDays || 0} onChange={event => setEditing({ ...editing, leadTimeDays: event.target.value })} /></label><label>Approval levels<input type="number" min="1" max="6" value={editing.approvalLevels || 1} onChange={event => setEditing({ ...editing, approvalLevels: event.target.value })} /></label><label>Status<select value={editing.status} onChange={event => setEditing({ ...editing, status: event.target.value })}><option>Draft</option><option>Active</option><option>Inactive</option></select></label></div><SaveBar onCancel={() => setEditing(null)} onSave={() => {}} label="Save calendar" /></form></section></div>}
  </WorkspaceShell>;
}

const settingsCatalog = {
  navigation: { title: 'Navigation Configuration', description: 'Maintain published guide/navigation items with valid module targets and ordered content.', key: 'atlas-settings-navigation-v1', fields: [['name', 'Name'], ['target', 'Target module'], ['stepOne', 'Step 1 content'], ['stepTwo', 'Step 2 content'], ['status', 'Status']], seeds: [{ id: 'nav-001', name: 'Company Information guide', target: 'Company Information', stepOne: 'Verify company identity and registrations.', stepTwo: 'Complete contacts, bank and signatories.', status: 'Published' }, { id: 'nav-002', name: 'Company Rules guide', target: 'Company Rules', stepOne: 'Select a subcategory and policy code.', stepTwo: 'Review and publish the assignment.', status: 'Draft' }] },
  faq: { title: 'FAQ and Self-Learning', description: 'Publish searchable, sanitized FAQ content at system or module scope.', key: 'atlas-settings-faq-v1', fields: [['category', 'Category'], ['question', 'Question'], ['answer', 'Answer'], ['scope', 'Scope'], ['status', 'Status']], seeds: [{ id: 'faq-001', category: 'Security', question: 'How is MFA enforced?', answer: 'MFA is required for sensitive actions and uses supported company methods.', scope: 'System', status: 'Published' }, { id: 'faq-002', category: 'Company Rules', question: 'Where do I configure an existing policy code?', answer: 'Open Company Rules and navigate to the linked policy engine template.', scope: 'Module', status: 'Published' }] },
  tickets: { title: 'Ticketing and Helpdesk', description: 'Configure supported topics and assignment destinations. Ticket creation persists first, then emits a retryable notification.', key: 'atlas-settings-tickets-v1', fields: [['name', 'Topic'], ['category', 'Category'], ['destination', 'Assignment destination'], ['sla', 'SLA'], ['status', 'Status']], seeds: [{ id: 'ticket-001', name: 'Payroll configuration', category: 'Configuration', destination: 'Payroll Support Queue', sla: '1 business day', status: 'Active' }, { id: 'ticket-002', name: 'Access request', category: 'Security', destination: 'Security Operations', sla: '4 hours', status: 'Active' }] },
};

export function SettingsConfigurationWorkspace({ kind, onBack, notify, companyId = activeCompanyId() }) {
  const definition = settingsCatalog[kind] || settingsCatalog.navigation;
  const [rows, setRows] = useState(() => {
    const scoped = readScopedRows(definition.key, definition.seeds, companyId);
    // Older builds called the ticket type name `topic`; normalize it once so
    // the admin configuration and the end-user ticket form share one contract.
    return kind === 'tickets' ? scoped.map(row => ({ ...row, name: row.name || row.topic || '' })) : scoped;
  });
  const [editing, setEditing] = useState(null);
  const [query, setQuery] = useState('');
  const targets = ['Company Information', 'Services Information', 'Calendar Settings', 'Employee Onboarding', 'Employee Charge Codes', 'Happiness Meter', 'Health & Wellness', 'Notifications', 'FAQ & Help', 'Company Rules', 'Connected Systems', 'Access & Approvals', 'Security Configuration', 'Reference Table', 'Tickets', 'Reports'];
  const save = event => { event.preventDefault(); const draft = { ...editing }; if (!definition.fields.every(([key]) => String(draft[key] || '').trim())) return notify({ type: 'error', message: 'Complete all required configuration fields before saving.' }); if (kind === 'navigation' && draft.status === 'Published' && !targets.includes(draft.target)) return notify({ type: 'error', message: 'Published navigation must target an existing Atlas module.' }); if (kind === 'faq') draft.answer = stripMarkup(draft.answer); const next = draft.id ? rows.map(row => row.id === draft.id ? draft : row) : [{ ...draft, id: `${kind}-${Date.now()}`, companyId }, ...rows]; setRows(next); writeScopedRows(definition.key, next, companyId); appendAuditEvent({ companyId, actor: 'Client Admin', action: `${definition.title.replaceAll(' ', '')}Updated`, entityType: definition.title, entityId: draft.id || 'new', summary: `${draft.status || 'Active'} configuration saved.` }); setEditing(null); notify({ type: 'success', message: `${definition.title} saved and audited.` }); };
  const visible = rows.filter(row => Object.values(row).join(' ').toLowerCase().includes(query.toLowerCase()));
  const archive = row => {
    const next = rows.map(item => item.id === row.id ? { ...item, status: kind === 'tickets' ? 'Inactive' : 'Archived' } : item);
    setRows(next);
    writeScopedRows(definition.key, next, companyId);
    appendAuditEvent({ companyId, actor: 'Client Admin', action: `${definition.title.replaceAll(' ', '')}${kind === 'tickets' ? 'Deactivated' : 'Archived'}`, entityType: definition.title, entityId: row.id, summary: `${row.name || row.topic || row.question || row.id} retained in history.` });
    notify({ type: 'success', message: 'Record archived/inactivated; history retained.' });
  };
  return <WorkspaceShell title={definition.title} description={definition.description} onBack={onBack} badge="Settings service"><div className="canonical-toolbar"><div className="search-box"><input value={query} onChange={event => setQuery(event.target.value)} placeholder={`Search ${definition.title.toLowerCase()}...`} /><MagnifyingGlass /></div><div className="toolbar-spacer" /><button className="button primary" onClick={() => setEditing(Object.fromEntries(definition.fields.map(([key]) => [key, key === 'status' ? (kind === 'tickets' ? 'Active' : 'Draft') : ''])))}><Plus /> Add</button></div><div className="canonical-callout"><FileText /><span>{kind === 'navigation' ? 'Publishing invalidates navigation cache and archived items remain in history.' : kind === 'faq' ? 'Rich text is sanitized before persistence; disable/archive is used instead of hard delete.' : 'Ticket Service persistence precedes notification delivery; failed notification remains retryable.'}</span></div><div className="table-card canonical-inner-table"><table><thead><tr>{definition.fields.map(([, label]) => <th key={label}>{label}</th>)}<th>Action</th></tr></thead><tbody>{visible.map(row => <tr key={row.id}>{definition.fields.map(([key]) => <td key={key}>{row[key] || '—'}</td>)}<td><div className="row-actions always"><button onClick={() => setEditing(row)} aria-label="Edit configuration"><PencilSimple /></button><button onClick={() => archive(row)} aria-label="Archive"><Eye /></button></div></td></tr>)}</tbody></table></div>{editing && <div className="modal-backdrop"><section className="modal canonical-modal"><header><h2>{editing.id ? 'Edit configuration' : 'Add configuration'}</h2><button className="icon-button" onClick={() => setEditing(null)}><X /></button></header><form onSubmit={save}><div className="canonical-form-grid">{definition.fields.map(([key, label]) => <label key={key}>{label}{key === 'answer' || key === 'stepOne' || key === 'stepTwo' ? <textarea required value={editing[key] || ''} onChange={event => setEditing({ ...editing, [key]: event.target.value })} /> : key === 'status' ? <select required value={editing[key] || ''} onChange={event => setEditing({ ...editing, [key]: event.target.value })}>{(kind === 'tickets' ? ['Active', 'Inactive'] : ['Draft', 'Published', 'Archived']).map(option => <option key={option}>{option}</option>)}</select> : key === 'target' ? <select required value={editing[key] || ''} onChange={event => setEditing({ ...editing, [key]: event.target.value })}><option value="">Select a module</option>{targets.map(option => <option key={option}>{option}</option>)}</select> : <input required value={editing[key] || ''} onChange={event => setEditing({ ...editing, [key]: event.target.value })} />}</label>)}</div><SaveBar onCancel={() => setEditing(null)} onSave={() => {}} label="Save configuration" /></form></section></div>}</WorkspaceShell>;
}

export function OvertimeGateway({ onBack, notify }) {
  // Reached from the Settings hub, not the Company Configuration sidebar that
  // ServiceConfiguration otherwise renders under — its default back label and
  // breadcrumb named a path this screen was never opened through.
  return <ServiceConfiguration moduleKey="overtime" onBack={onBack} notify={notify} backLabel="Settings" breadcrumb="Settings / Overtime Rate Management" />;
}
